solution.solution.cpp:
class Calc
{
public:
    Calc& add(int n) { m_value += n; return *this; }
    Calc& subtract(int n) { m_value -= n; return *this; }
    Calc& multiply(int n) { m_value *= n; return *this; }
    int value() const { return m_value; }

private:
    int m_value{ 0 };
};

unitTests:
TEST("a chain") { Calc c{}; CHECK_EQ(c.add(5).multiply(3).subtract(1).value(), 14); }
TEST("the chain changed the original object, not a copy") { Calc c{}; c.add(2).add(2).add(2); CHECK_EQ(c.value(), 6); }
TEST("separate calls") { Calc c{}; c.add(10); c.multiply(10); CHECK_EQ(c.value(), 100); }

